import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { TransacaoService, Transacao } from '../../services/transacao.service';
import { CategoriaService, Categoria } from '../../services/categoria.service';
import { ExportService } from '../../services/export.service';
import { TranslationPipe } from '../../core/i18n/translation.pipe';
import { I18nService } from '../../core/i18n/i18n.service';

@Component({
  selector: 'app-transacoes',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, TranslationPipe],
  templateUrl: './transacoes.component.html',
  styleUrls: ['./transacoes.component.scss']
})
export class TransacoesComponent implements OnInit {
  transacoes: Transacao[] = [];
  mostrarForm = false;
  isLoading = false;
  isSaving = false;
  isExporting = false;
  hasError = false;
  errorMessage = '';
  editandoId: number | null = null;

  transacaoForm: FormGroup;
  categorias: Categoria[] = [];

  constructor(
    private transacaoService: TransacaoService,
    private categoriaService: CategoriaService,
    private exportService: ExportService,
    private fb: FormBuilder,
    private i18nService: I18nService
  ) {
    this.transacaoForm = this.criarFormulario();
  }

  ngOnInit(): void {
    this.carregarTransacoes();
    this.carregarCategorias();
  }

  private criarFormulario(): FormGroup {
    return this.fb.group({
      categoria_id: ['', [Validators.required]],
      valor: ['', [Validators.required, Validators.min(0.01)]],
      tipo: ['receita', [Validators.required]],
      data: ['', [Validators.required]],
      descricao: ['', [Validators.required, Validators.minLength(3)]]
    });
  }

  private resetarFormulario(): void {
    this.transacaoForm.reset({
      categoria_id: '',
      valor: '',
      tipo: 'receita',
      data: this.obterDataAtual(),
      descricao: ''
    });
    this.editandoId = null;
  }

  private obterDataAtual(): string {
    const hoje = new Date();
    return hoje.toISOString().split('T')[0];
  }

  private formatarMoeda(valor: number): string {
    return new Intl.NumberFormat('pt-AO', {
      style: 'currency',
      currency: 'AOA',
      currencyDisplay: 'narrowSymbol'
    }).format(valor);
  }

  carregarTransacoes(): void {
    this.isLoading = true;
    this.hasError = false;

    this.transacaoService.listar().subscribe({
      next: (response) => {
        if (response.success && response.data) {
          const data = response.data as Transacao[];
          this.transacoes = Array.isArray(data) ? data : [data];
        } else {
          this.transacoes = [];
        }
        this.isLoading = false;
      },
      error: (error) => {
        console.error('Erro ao carregar transacoes:', error);
        this.hasError = true;
        this.errorMessage = this.i18nService.translate('transactions.loadError');
        this.isLoading = false;
      }
    });
  }

  carregarCategorias(): void {
    this.categoriaService.listar().subscribe({
      next: (response) => {
        if (response.success && response.data) {
          const data = response.data as Categoria[];
          this.categorias = Array.isArray(data) ? data : [data];
        } else {
          this.categorias = [];
        }
      },
      error: () => {
        this.categorias = [];
      }
    });
  }

  toggleFormulario(): void {
    this.mostrarForm = !this.mostrarForm;
    if (!this.mostrarForm) {
      this.resetarFormulario();
    } else {
      this.transacaoForm.patchValue({ data: this.obterDataAtual() });
    }
  }

  editar(transacao: Transacao): void {
    this.editandoId = transacao.id || null;
    this.transacaoForm.patchValue({
      categoria_id: transacao.categoria_id,
      valor: transacao.valor,
      tipo: transacao.tipo,
      data: transacao.data,
      descricao: transacao.descricao
    });
    this.mostrarForm = true;
  }

  cancelar(): void {
    this.mostrarForm = false;
    this.resetarFormulario();
  }

  salvar(): void {
    if (!this.transacaoForm.valid) {
      this.errorMessage = this.i18nService.translate('transactions.invalidForm');
      return;
    }

    this.isSaving = true;
    const formValue = this.transacaoForm.value;

    if (this.editandoId) {
      this.transacaoService.atualizar(this.editandoId, formValue).subscribe({
        next: () => {
          this.carregarTransacoes();
          this.cancelar();
          this.isSaving = false;
        },
        error: () => {
          this.errorMessage = this.i18nService.translate('transactions.updateError');
          this.isSaving = false;
        }
      });
    } else {
      this.transacaoService.criar(formValue).subscribe({
        next: () => {
          this.carregarTransacoes();
          this.cancelar();
          this.isSaving = false;
        },
        error: () => {
          this.errorMessage = this.i18nService.translate('transactions.createError');
          this.isSaving = false;
        }
      });
    }
  }

  exportarRelatorio(): void {
    this.isExporting = true;
    this.hasError = false;

    this.exportService.exportarCsv('relatorio_transacoes.csv')
      .then(() => {
        this.isExporting = false;
      })
      .catch((error) => {
        this.errorMessage = error.message || this.i18nService.translate('transactions.exportError');
        this.hasError = true;
        this.isExporting = false;
      });
  }

  deletar(transacao: Transacao): void {
    if (!transacao.id) return;

    if (confirm(`Tem a certeza que deseja eliminar esta transacao (${this.formatarMoeda(transacao.valor)})?`)) {
      this.transacaoService.remover(transacao.id).subscribe({
        next: () => {
          this.carregarTransacoes();
        },
        error: () => {
          this.errorMessage = this.i18nService.translate('transactions.deleteError');
        }
      });
    }
  }

  obterNomeCategoria(categoriaId: number): string {
    return this.categorias.find((c) => c.id === categoriaId)?.nome || this.i18nService.translate('transactions.unknownCategory');
  }

  formatarValor(valor: number): string {
    return this.formatarMoeda(valor);
  }

  formatarData(data: string): string {
    const date = new Date(data + 'T00:00:00');
    return new Intl.DateTimeFormat('pt-PT').format(date);
  }

  getTituloFormulario(): string {
    return this.editandoId
      ? this.i18nService.translate('transactions.editTitle')
      : this.i18nService.translate('transactions.createTitle');
  }

  getTextoBotaoSalvar(): string {
    return this.i18nService.translate('transactions.save');
  }
}
<div class="transacoes-container">
  <div class="transacoes-header">
    <div>
      <h2>{{ 'transactions.title' | t }}</h2>
      <p>{{ 'transactions.subtitle' | t }}</p>
    </div>

    <div class="header-actions">
      <button class="btn-outline" (click)="exportarRelatorio()" [disabled]="isLoading || isExporting">
        <span *ngIf="!isExporting">{{ 'transactions.exportReport' | t }}</span>
        <span *ngIf="isExporting">{{ 'dashboard.exporting' | t }}</span>
      </button>

      <button class="btn-primary" (click)="toggleFormulario()" [disabled]="isLoading">
        <span *ngIf="!mostrarForm">{{ 'transactions.newTransaction' | t }}</span>
        <span *ngIf="mostrarForm">{{ 'transactions.close' | t }}</span>
      </button>
    </div>
  </div>

  <div *ngIf="hasError" class="alert-error">
    <strong>{{ 'transactions.error' | t }}:</strong> {{ errorMessage }}
    <button class="alert-close" (click)="hasError = false">X</button>
  </div>

  <div *ngIf="isLoading" class="loading-container">
    <div class="spinner"></div>
    <p>{{ 'transactions.loading' | t }}</p>
  </div>

  <div *ngIf="!isLoading && transacoes.length === 0 && !mostrarForm" class="empty-state">
    <div class="empty-icon">{{ 'transactions.error' | t }}</div>
    <h3>{{ 'transactions.noDataTitle' | t }}</h3>
    <p>{{ 'transactions.noDataText' | t }}</p>
    <button class="btn-primary" (click)="toggleFormulario()">{{ 'transactions.firstTransaction' | t }}</button>
  </div>

  <section *ngIf="!isLoading && transacoes.length > 0 && !mostrarForm" class="extrato-lista">
    <article class="extrato-item" *ngFor="let t of transacoes" [class.tipo-receita]="t.tipo === 'receita'" [class.tipo-despesa]="t.tipo === 'despesa'">
      <div class="item-left">
        <div class="tipo-indicador" [class.receita]="t.tipo === 'receita'" [class.despesa]="t.tipo === 'despesa'">
          <span *ngIf="t.tipo === 'receita'">R</span>
          <span *ngIf="t.tipo === 'despesa'">D</span>
        </div>

        <div class="item-info">
          <strong>{{ t.descricao }}</strong>
          <div class="item-subinfo">
            <span>{{ formatarData(t.data) }}</span>
            <span class="dot">-</span>
            <span>{{ obterNomeCategoria(t.categoria_id) }}</span>
          </div>
        </div>
      </div>

      <div class="item-right">
        <div class="valor" [class.receita]="t.tipo === 'receita'" [class.despesa]="t.tipo === 'despesa'">
          {{ t.tipo === 'receita' ? '+' : '-' }} {{ formatarValor(t.valor) }}
        </div>

        <div class="item-actions">
          <button class="icon-btn" (click)="editar(t)" [title]="'transactions.edit' | t">{{ 'transactions.edit' | t }}</button>
          <button class="icon-btn danger" (click)="deletar(t)" [title]="'transactions.delete' | t">{{ 'transactions.delete' | t }}</button>
        </div>
      </div>
    </article>
  </section>

  <div class="modal-backdrop" *ngIf="mostrarForm" (click)="cancelar()">
    <div class="modal-card" (click)="$event.stopPropagation()">
      <div class="modal-header">
        <h3>{{ getTituloFormulario() }}</h3>
        <button type="button" class="icon-btn" (click)="cancelar()">X</button>
      </div>

      <form [formGroup]="transacaoForm" (ngSubmit)="salvar()" class="transacao-form">
        <div class="form-group">
          <label for="categoria_id">{{ 'transactions.category' | t }}</label>
          <select id="categoria_id" formControlName="categoria_id" class="form-control">
            <option value="">{{ 'transactions.selectCategory' | t }}</option>
            <option *ngFor="let cat of categorias" [value]="cat.id">{{ cat.nome }}</option>
          </select>
        </div>

        <div class="form-group">
          <label>{{ 'transactions.type' | t }}</label>
          <div class="tipo-options">
            <label class="pill-option receita">
              <input type="radio" value="receita" formControlName="tipo" /> {{ 'transactions.income' | t }}
            </label>
            <label class="pill-option despesa">
              <input type="radio" value="despesa" formControlName="tipo" /> {{ 'transactions.expense' | t }}
            </label>
          </div>
        </div>

        <div class="form-grid">
          <div class="form-group">
            <label for="valor">{{ 'transactions.value' | t }}</label>
            <input id="valor" type="number" formControlName="valor" step="0.01" min="0" class="form-control" placeholder="0.00" />
          </div>

          <div class="form-group">
            <label for="data">{{ 'transactions.date' | t }}</label>
            <input id="data" type="date" formControlName="data" class="form-control" />
          </div>
        </div>

        <div class="form-group">
          <label for="descricao">{{ 'transactions.description' | t }}</label>
          <textarea id="descricao" formControlName="descricao" rows="3" class="form-control" [placeholder]="'transactions.descriptionPlaceholder' | t"></textarea>
        </div>

        <div class="form-actions">
          <button type="button" class="btn-secondary" (click)="cancelar()" [disabled]="isSaving">{{ 'transactions.cancel' | t }}</button>
          <button type="submit" class="btn-primary" [disabled]="!transacaoForm.valid || isSaving">
            <span *ngIf="!isSaving">{{ getTextoBotaoSalvar() }}</span>
            <span *ngIf="isSaving">{{ 'transactions.saving' | t }}</span>
          </button>
        </div>
      </form>
    </div>
  </div>
</div>
